fn digest_mix(digest: u64, word: u64) -> u64 {
    (digest ^ word).wrapping_mul(DIGEST_PRIME)
}

fn port128_words(value: Port128) -> (u64, u64) {
    (value.lo, value.hi)
}

fn c128_words(value: C128) -> (u64, u64) {
    (value.w[0], value.w[1])
}

/// Evaluates one case through both legs of one lane. It is the single
/// operand/mode/dispatch fan-out shared by the exhaustive sweep and the
/// routing sentinels. Results are returned as (lo, hi) words: 32/64-bit
/// results occupy lo with hi=0; the 128-bit promotion returns the
/// little-endian memory-image words.
fn d32_exhaustive_legs(op: Op, native_mode: i64, x: u32) -> (u64, u64, u32, u64, u64, u32) {
    let mut c_flags = 0u32;
    match op {
        Op::Sqrt => {
            let nb = unsafe { libbid_sys::bid32_sqrt(x, native_mode as u32, &mut c_flags) };
            let (pb, pf) = port_bid32_sqrt(x, native_mode);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::RoundIntegralExact => {
            let nb = unsafe { c_bid32_round_integral_exact(x, native_mode as u32, &mut c_flags) };
            let (pb, pf) = port_bid32_round_integral_exact(x, native_mode);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::RoundIntegralNearestEven => {
            let nb = unsafe { c_bid32_round_integral_nearest_even(x, &mut c_flags) };
            let (pb, pf) = port_bid32_round_integral_nearest_even(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::RoundIntegralNearestAway => {
            let nb = unsafe { c_bid32_round_integral_nearest_away(x, &mut c_flags) };
            let (pb, pf) = port_bid32_round_integral_nearest_away(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::RoundIntegralZero => {
            let nb = unsafe { c_bid32_round_integral_zero(x, &mut c_flags) };
            let (pb, pf) = port_bid32_round_integral_zero(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::RoundIntegralPositive => {
            let nb = unsafe { c_bid32_round_integral_positive(x, &mut c_flags) };
            let (pb, pf) = port_bid32_round_integral_positive(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::RoundIntegralNegative => {
            let nb = unsafe { c_bid32_round_integral_negative(x, &mut c_flags) };
            let (pb, pf) = port_bid32_round_integral_negative(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::ToBid64 => {
            let nb = unsafe { libbid_sys::bid32_to_bid64(x, &mut c_flags) };
            let (pb, pf) = port_bid32_to_bid64(x);
            (nb, 0, c_flags, pb, 0, pf)
        }
        Op::ToBid128 => {
            let nv = unsafe { libbid_sys::bid32_to_bid128(x, &mut c_flags) };
            let (n_lo, n_hi) = c128_words(nv);
            let (pv, pf) = port_bid32_to_bid128(x);
            let (p_lo, p_hi) = port128_words(pv);
            (n_lo, n_hi, c_flags, p_lo, p_hi, pf)
        }
        Op::NextUp => {
            let nb = unsafe { c_bid32_nextup(x, &mut c_flags) };
            let (pb, pf) = port_bid32_next_up(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::NextDown => {
            let nb = unsafe { c_bid32_nextdown(x, &mut c_flags) };
            let (pb, pf) = port_bid32_next_down(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
        Op::Logb => {
            let nb = unsafe { c_bid32_logb(x, &mut c_flags) };
            let (pb, pf) = port_bid32_logb(x);
            (nb as u64, 0, c_flags, pb as u64, 0, pf)
        }
    }
}

/// Result width of one lane operation for diagnostic and sentinel-leg
/// formatting.
fn result_bits(op: Op) -> u32 {
    match op {
        Op::ToBid64 => 64,
        Op::ToBid128 => 128,
        _ => 32,
    }
}

fn format_result(op: Op, lo: u64, hi: u64, flags: u32) -> String {
    match result_bits(op) {
        64 => format!("{lo:016x}/{flags:08x}"),
        128 => format!("{hi:016x}:{lo:016x}/{flags:08x}"),
        _ => format!("{:08x}/{flags:08x}", lo as u32),
    }
}

/// Buckets one input bit pattern for mismatch reporting (diagnostic only; no
/// gate decision depends on it). Mirrors the generated Go leg's classifier.
fn classify(x: u32) -> &'static str {
    let masked = x & 0x7fff_ffff;
    if masked & 0x7e00_0000 == 0x7e00_0000 {
        return "snan";
    }
    if masked & 0x7c00_0000 == 0x7c00_0000 {
        return "qnan";
    }
    if masked & 0x7800_0000 == 0x7800_0000 {
        return "infinity";
    }
    let coefficient = if masked & 0x6000_0000 == 0x6000_0000 {
        0x80_0000 | (masked & 0x1f_ffff)
    } else {
        masked & 0x7f_ffff
    };
    if coefficient > 9_999_999 {
        "noncanonical_coefficient"
    } else if coefficient == 0 {
        "zero"
    } else {
        "finite"
    }
}

#[derive(Default)]
struct LaneRecorder {
    total: u64,
    by_class: std::collections::BTreeMap<&'static str, u64>,
    detail: Vec<String>,
}

impl LaneRecorder {
    fn record(&mut self, op: Op, x: u32, n_lo: u64, n_hi: u64, n_flags: u32, p_lo: u64, p_hi: u64, p_flags: u32) {
        let class = classify(x);
        self.total += 1;
        *self.by_class.entry(class).or_insert(0) += 1;
        if self.detail.len() < MISMATCH_DETAIL_CAP {
            self.detail.push(format!(
                "x={x:08x} class={class} C={} port={}",
                format_result(op, n_lo, n_hi, n_flags),
                format_result(op, p_lo, p_hi, p_flags)
            ));
        }
    }

    fn merge(&mut self, other: LaneRecorder) {
        self.total += other.total;
        for (class, count) in other.by_class {
            *self.by_class.entry(class).or_insert(0) += count;
        }
        for line in other.detail {
            if self.detail.len() < MISMATCH_DETAIL_CAP {
                self.detail.push(line);
            }
        }
    }

    fn report(&self, lane: &Lane) {
        if self.total == 0 {
            return;
        }
        let summary: Vec<String> = self
            .by_class
            .iter()
            .map(|(class, count)| format!("{class}={count}"))
            .collect();
        panic!(
            "Rust decimal32 exhaustive lane {}: {} mismatching cases (by input class: {}); first {} in full detail:\n{}",
            lane.name,
            self.total,
            summary.join(" "),
            self.detail.len(),
            self.detail.join("\n")
        );
    }
}

#[derive(Clone, Copy)]
struct Shard {
    count: u64,
    index: u64,
}

/// Reads the optional chunk-level shard split. A sharded run is a development
/// aid: it suppresses the per-lane digests (they are defined over the full
/// ordered space only) and cannot produce the full-count evidence lines
/// cmd/verifylog requires.
fn load_shard() -> Shard {
    let count_text = std::env::var("BID754_D32_EXHAUSTIVE_SHARD_COUNT").unwrap_or_default();
    let index_text = std::env::var("BID754_D32_EXHAUSTIVE_SHARD_INDEX").unwrap_or_default();
    if count_text.is_empty() && index_text.is_empty() {
        return Shard { count: 1, index: 0 };
    }
    assert!(
        !count_text.is_empty() && !index_text.is_empty(),
        "BID754_D32_EXHAUSTIVE_SHARD_COUNT and BID754_D32_EXHAUSTIVE_SHARD_INDEX must be set together"
    );
    let count: u64 = count_text
        .parse()
        .unwrap_or_else(|_| panic!("invalid BID754_D32_EXHAUSTIVE_SHARD_COUNT {count_text:?}"));
    assert!(count != 0, "invalid BID754_D32_EXHAUSTIVE_SHARD_COUNT {count_text:?}");
    let index: u64 = index_text
        .parse()
        .unwrap_or_else(|_| panic!("invalid BID754_D32_EXHAUSTIVE_SHARD_INDEX {index_text:?}"));
    assert!(index < count, "invalid BID754_D32_EXHAUSTIVE_SHARD_INDEX {index_text:?} for shard count {count}");
    Shard { count, index }
}

impl Shard {
    fn owns(&self, chunk: u64) -> bool {
        chunk % self.count == self.index
    }

    fn owned_chunks(&self, total: u64) -> u64 {
        if total <= self.index {
            return 0;
        }
        1 + (total - 1 - self.index) / self.count
    }
}

/// Sweeps one contiguous chunk of one lane in ascending input order and
/// returns the chunk's ordered result digest.
fn run_chunk(lane: &Lane, chunk: u64, recorder: &mut LaneRecorder) -> u64 {
    let start = chunk << CHUNK_BITS;
    let end = start + (1u64 << CHUNK_BITS);
    let mut digest = DIGEST_OFFSET;
    for x in start..end {
        let (n_lo, n_hi, n_flags, p_lo, p_hi, p_flags) = d32_exhaustive_legs(lane.op, lane.native_mode, x as u32);
        if n_lo != p_lo || n_hi != p_hi || n_flags != p_flags {
            recorder.record(lane.op, x as u32, n_lo, n_hi, n_flags, p_lo, p_hi, p_flags);
        }
        digest = digest_mix(digest, n_lo);
        digest = digest_mix(digest, n_hi);
        digest = digest_mix(digest, n_flags as u64);
        digest = digest_mix(digest, p_lo);
        digest = digest_mix(digest, p_hi);
        digest = digest_mix(digest, p_flags as u64);
    }
    digest
}

/// Executes one lane's owned chunks across worker threads. Chunk digests are
/// folded in ascending chunk order after every worker finishes, so the lane
/// digest is deterministic regardless of scheduling; it is only defined (and
/// only printed) on unsharded runs.
fn run_lane(lane: &Lane, shard: Shard) -> (u64, u64, bool, LaneRecorder) {
    let chunk_digests: Vec<AtomicU64> = (0..CHUNK_COUNT).map(|_| AtomicU64::new(0)).collect();
    let owned_total = shard.owned_chunks(CHUNK_COUNT);
    let workers = std::thread::available_parallelism().map_or(1, |n| n.get());
    let next = AtomicU64::new(0);
    let merged = Mutex::new(LaneRecorder::default());
    std::thread::scope(|scope| {
        for _ in 0..workers {
            scope.spawn(|| {
                let mut local = LaneRecorder::default();
                loop {
                    let chunk = next.fetch_add(1, Ordering::Relaxed);
                    if chunk >= CHUNK_COUNT {
                        break;
                    }
                    if !shard.owns(chunk) {
                        continue;
                    }
                    let digest = run_chunk(lane, chunk, &mut local);
                    chunk_digests[chunk as usize].store(digest, Ordering::Relaxed);
                }
                merged.lock().unwrap().merge(local);
            });
        }
    });
    let executed = owned_total << CHUNK_BITS;
    let digest_complete = shard.count == 1;
    let mut digest = 0u64;
    if digest_complete {
        digest = DIGEST_OFFSET;
        for chunk_digest in &chunk_digests {
            digest = digest_mix(digest, chunk_digest.load(Ordering::Relaxed));
        }
        digest = digest_mix(digest, CASES_PER_LANE);
    }
    let recorder = merged.into_inner().unwrap();
    (executed, digest, digest_complete, recorder)
}

/// Parses one pinned sentinel row:
///
///     d32 <op> x=<8-hex> [m=<mode>] -> <expected leg text>
///
/// and resolves it to a lane through the same lane table the exhaustive sweep
/// dispatches from.
fn parse_sentinel_row(row_index: usize, row: &str) -> (&'static Lane, u32, &str) {
    let fail = |reason: &str| -> ! {
        panic!("sentinel row {row_index} is malformed ({reason}): {row:?}");
    };
    let Some((head, want)) = row.split_once(" -> ") else {
        fail("no -> separator");
    };
    let fields: Vec<&str> = head.split_whitespace().collect();
    if fields.len() < 3 || fields[0] != "d32" {
        fail("head is not `d32 <op> x=... [m=...]`");
    }
    let op_token = fields[1];
    if !fields[2].starts_with("x=") || fields[2].len() != 2 + 8 {
        fail("operand is not x=<8-hex>");
    }
    let Ok(parsed) = u32::from_str_radix(&fields[2][2..], 16) else {
        fail("operand is not valid hex");
    };
    let mut mode: i64 = -1;
    match fields.len() {
        3 => {}
        4 => {
            if !fields[3].starts_with("m=") {
                fail("fourth token is not m=<mode>");
            }
            match fields[3][2..].parse::<i64>() {
                Ok(parsed_mode) if (0..=4).contains(&parsed_mode) => mode = parsed_mode,
                _ => fail("mode is not a native rounding mode 0..4"),
            }
        }
        _ => fail("unexpected token count"),
    }
    for lane in LANES.iter() {
        if lane.op_token == op_token && lane.native_mode == mode {
            return (lane, parsed, want);
        }
    }
    fail("no lane matches the (op, mode) pair");
}

/// Closes the generated lane and sentinel inventories against the generated
/// count constants before the long sweep spends any time.
#[test]
fn generated_d32_exhaustive_lane_contract() {
    assert_eq!(LANES.len() as u64, LANE_COUNT, "lane table size diverges from the generated constant");
    assert_eq!(
        D32_EXHAUSTIVE_LANE_NAMES.len() as u64,
        LANE_COUNT,
        "lane name inventory size diverges from the generated constant"
    );
    let mut names = std::collections::HashSet::new();
    let mut ops = std::collections::HashSet::new();
    let mut modes_by_op: std::collections::HashMap<Op, std::collections::HashSet<i64>> = std::collections::HashMap::new();
    for (i, lane) in LANES.iter().enumerate() {
        assert_eq!(
            lane.name, D32_EXHAUSTIVE_LANE_NAMES[i],
            "lane {i} name diverges from the lane-name inventory"
        );
        assert!(names.insert(lane.name), "duplicate lane name {:?}", lane.name);
        ops.insert(lane.op);
        assert!(
            modes_by_op.entry(lane.op).or_default().insert(lane.native_mode),
            "duplicate (op, mode) lane {:?}",
            lane.name
        );
        if is_mode_taking(lane.op) {
            assert!(
                (0..=4).contains(&lane.native_mode),
                "mode-taking lane {:?} carries native mode {} outside 0..4",
                lane.name,
                lane.native_mode
            );
        } else {
            assert_eq!(
                lane.native_mode, -1,
                "fixed-attribute lane {:?} carries native mode {}, want -1",
                lane.name, lane.native_mode
            );
        }
    }
    assert_eq!(ops.len() as u64, OPERATION_COUNT, "distinct operation count diverges from the generated constant");
    for op in MODE_TAKING_OPS {
        assert_eq!(
            modes_by_op.get(&op).map_or(0, |modes| modes.len()),
            5,
            "mode-taking operation {op:?} does not cover all 5 modes"
        );
    }
    assert_eq!(CHUNK_COUNT << CHUNK_BITS, CASES_PER_LANE, "chunk split does not cover the per-lane space");
    assert_eq!(
        LANE_COUNT * CASES_PER_LANE,
        TOTAL_COMPARISONS,
        "lane count x per-lane space does not equal the generated total"
    );
    assert_eq!(
        D32_EXHAUSTIVE_SENTINEL_ROWS.len() as u64,
        SENTINEL_ROW_COUNT,
        "sentinel row literal count diverges from the generated constant"
    );
    let mut covered = std::collections::HashSet::new();
    for (row_index, row) in D32_EXHAUSTIVE_SENTINEL_ROWS.iter().enumerate() {
        let (lane, _, _) = parse_sentinel_row(row_index, row);
        covered.insert(lane.name);
    }
    for lane in LANES.iter() {
        assert!(
            covered.contains(lane.name),
            "lane {:?} is not covered by any routing-sentinel row",
            lane.name
        );
    }
    println!(
        "Rust decimal32 exhaustive unary lane contract: lanes={LANE_COUNT} operations={OPERATION_COUNT} cases_per_lane={CASES_PER_LANE} total={TOTAL_COMPARISONS}"
    );
}

/// Replays the pinned known-answer rows through the same lane dispatch the
/// exhaustive sweep uses and requires pinned == Intel C == Rust port on every
/// row.
#[test]
fn generated_d32_exhaustive_routing_sentinels() {
    let mut executed = 0u64;
    for (row_index, row) in D32_EXHAUSTIVE_SENTINEL_ROWS.iter().enumerate() {
        let (lane, x, want) = parse_sentinel_row(row_index, row);
        let (n_lo, n_hi, n_flags, p_lo, p_hi, p_flags) = d32_exhaustive_legs(lane.op, lane.native_mode, x);
        let native = format_result(lane.op, n_lo, n_hi, n_flags);
        let port = format_result(lane.op, p_lo, p_hi, p_flags);
        assert_eq!(
            native, want,
            "sentinel row {row_index} ({row}): Intel C leg diverges from the pinned expectation"
        );
        assert_eq!(
            port, want,
            "sentinel row {row_index} ({row}): Rust port leg diverges from the pinned expectation"
        );
        executed += 1;
    }
    assert_eq!(executed, SENTINEL_ROW_COUNT, "executed sentinel row count diverges from the generated constant");
    println!("Rust d32 exhaustive routing sentinels: {executed}/{executed}");
}

/// The long gate: every lane, every 32-bit input, bit+flag exact.
#[test]
fn generated_d32_exhaustive_unary_differential() {
    let shard = load_shard();
    let mut total_executed = 0u64;
    for lane in LANES.iter() {
        let (executed, digest, digest_complete, recorder) = run_lane(lane, shard);
        total_executed += executed;
        recorder.report(lane);
        if digest_complete {
            println!(
                "Rust decimal32 exhaustive lane {}: exact comparisons {executed}/{CASES_PER_LANE} digest={digest}",
                lane.name
            );
        } else {
            println!(
                "Rust decimal32 exhaustive lane {}: exact comparisons {executed}/{CASES_PER_LANE} (sharded run; lane digest suppressed)",
                lane.name
            );
        }
    }
    if shard.count == 1 {
        assert_eq!(total_executed, TOTAL_COMPARISONS, "executed comparison total diverges from the generated constant");
    }
    println!("Rust decimal32 exhaustive unary total comparisons: {total_executed}/{TOTAL_COMPARISONS}");
}
